import { Component, For, onMount, Show } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-compat.jsx";
import { TicketBox } from "#core/ui-next/screens/create-game/ticket-box.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { LayoutModel, useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import {
	createGovtChooserModel,
	GovtChooserModelContext,
} from "#base/ui/government-chooser/government-chooser-model.js";
import { GovtEffectItem, TraditionDisplayItem } from "#base/ui/policies/model-government.js";
import { TicketSection } from "#base/ui-next/tooltips/plot-tooltip/components/utility.jsx";

import styles from "./screen-government-chooser.scss?url";

interface GovernmentChooserProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

const GovernmentChooserComponent: Component<GovernmentChooserProps> = (props) => {
	const model = createGovtChooserModel();
	const audio = useAudio("GovernmentScreen");
	const layout = LayoutModel.get();

	const isSmallScreen = useIsSmallScreen() || layout.screenWidth() / layout.screenHeight() < 1.34;

	function handleOnCancelInput() {
		model.onCloseClicked();
		audio("popup-close");
	}

	onMount(() => {
		audio("popup-open");
	});

	return (
		<NestedTooltipContext.Provider value={{ disabled: true }}>
			<GovtChooserModelContext.Provider value={model}>
				<AudioContextProvider segment="GovernmentScreen">
					<Panel
						ref={props.ref}
						name="Government Chooser"
						id="screen-government-chooser"
						onCancelInput={() => handleOnCancelInput()}
					>
						<div class="bg-cover government-frame-bg bg-no-repeat relative max-h-full">
							<div
								class="size-64 absolute top-4 left-4 bg-contain bg-no-repeat"
								style={{ "background-image": "url(blp:base_frame-filigree)", opacity: "0.1" }}
							/>
							<div
								class="size-64 absolute top-4 right-4 bg-contain bg-no-repeat rotate-90"
								style={{ "background-image": "url(blp:base_frame-filigree)", opacity: "0.1" }}
							/>
							<div class="inset-0 absolute government-screen-bg bg-cover bg-no-repeat" />

							<div class="relative flex items-center flex-col flex-auto">
								<Filigree.TitleAccent filigreeClass="mt-5">
									<L10n.Stylize
										text="LOC_UI_GOVERNMENT_PICKER_TITLE"
										class={`gov-chooser-header items-center justify-center flex mt-4 font-bold fxs-header tracking-100 uppercase ${isSmallScreen() ? "py-1 font-title-lg" : "py-4 font-title-2xl"} text-shadow-subtle`}
									/>
								</Filigree.TitleAccent>
								<ScrollArea class="flex-auto p-4">
									<SpatialSlot
										name="government-scrollable"
										class={`flex w-full ${isSmallScreen() ? "flex-col" : "flex-row"} px-8 pt-2 flex-auto justify-center w-full items-center self-center`}
									>
										<For each={model.choicesAvailable}>
											{(item) => (
												<GovernmentChooserItem
													itemName={item.governmentName}
													celebrationOptions={item.celebrationItems}
													onClick={model.onCardClick(item.governmentType)}
													isSelected={model.currentlySelectedChoice == item.governmentType}
													passiveEffect={item.governmentPassive}
													traditionsUnlocked={item.traditionsUnlocked}
												/>
											)}
										</For>
									</SpatialSlot>
								</ScrollArea>

								<CloseButton
									class={`${IsControllerActive() ? "hidden" : ""} absolute right-1 top-1`}
									onActivate={() => {
										handleOnCancelInput();
									}}
									hotkeyAction="cancel"
									navTrayText="LOC_GENERIC_BACK"
								/>
								<Button
									class={`flex w-72 m-6`}
									onActivate={model.onConfirmClicked}
									disabled={model.currentlySelectedChoice === null}
									classList={{
										hidden: IsControllerActive(),
									}}
									disableFocus={IsControllerActive()}
									hotkeyAction="shell-action-1"
									navTrayText="LOC_GENERIC_CONFIRM"
								>
									<L10n.Compose text={"LOC_GENERIC_CONFIRM"} />
								</Button>
							</div>
						</div>
					</Panel>
				</AudioContextProvider>
			</GovtChooserModelContext.Provider>
		</NestedTooltipContext.Provider>
	);
};

interface GovernmentChooserItemProps {
	itemName: string;
	passiveEffect?: string;
	celebrationOptions: GovtEffectItem[];
	traditionsUnlocked: TraditionDisplayItem[];
	onClick: void;
	isSelected: boolean;
}

export const GovernmentChooserItem: Component<GovernmentChooserItemProps> = (props) => {
	const layout = LayoutModel.get();
	const isSmallScreen = useIsSmallScreen() || layout.screenWidth() / layout.screenHeight() < 1.34;

	return (
		<Activatable
			class={`flex gov-chooser-item relative ${isSmallScreen() ? "flex-auto w-full" : "flex-1 h-full mx-2"}`}
			onActivate={() => props.onClick}
			audio={{
				onActivate: "data-audio-government-clicked",
				onFocus: "data-audio-primary-button-focus",
			}}
		>
			<TicketBox class="relative flex flex-auto flex-col px-8 pb-8 pt-3 mb-4">
				<div class="absolute top-0 right-1\.5 left-0 bottom-2\.5 gov-chooser-hover" />
				<Show when={props.isSelected}>
					<div class="absolute -top-1\.5 -right-0 -left-1 bottom-1 gov-chooser-selected" />
					<div class="absolute top-0\.5 right-2\.5 left-1 bottom-3\.5 gov-chooser-hover" />
				</Show>
				<div class="flex flex-col justify-start mb-6">
					<L10n.Stylize
						class="font-title-xl py-2 tracking-100 uppercase text-accent-1 flex font-fit-shrink"
						text={props.itemName}
					/>
					<div class="government-fade-divider w-full h-1" />
					<GovtCardSubHeader
						text={"LOC_UI_GOVERNMENT_ABILITY"}
						secondaryText={true}
						class={"mt-4 mb-1"}
					/>
					<Show when={props.passiveEffect}>
						<div class="bg-primary-4 border-primary-4 mr-1">
							<L10n.Stylize
								class="font-body-base p-4 flex flex-auto text-accent-3"
								text={props.passiveEffect ?? ""}
							/>
						</div>
					</Show>
				</div>
				<div class="flex flex-auto flex-col">
					<GovtCardSubHeader
						secondaryText={true}
						text={"LOC_UI_CELEBRATION_OPTIONS"}
					/>
					<TicketSection>
						<For each={props.celebrationOptions}>
							{(item) => (
								<div class="flex flex-col">
									<div class="flex flex-row p-1 items-center">
										<Icon
											class="size-8"
											name={item.image}
											isUrl={true}
										/>
										<Divider vertical={true} />
										<L10n.Stylize
											class="flex flex-auto font-body-sm w-full"
											text={item.description}
										/>
									</div>
									<Show when={item != props.celebrationOptions[props.celebrationOptions.length - 1]}>
										<Divider />
									</Show>
								</div>
							)}
						</For>
					</TicketSection>
					<GovtCardSubHeader
						secondaryText={true}
						class={"mt-5 mb-1"}
						text={"LOC_UI_TRADITIONS_TITLE"}
					/>
					<div class="relative">
						<div class="absolute bg-glow top-0 right-0 left-0 bottom-2" />
						<TicketBox class="relative -mr-1\.5 -ml-0\.5">
							<For each={props.traditionsUnlocked}>
								{(item) => (
									<div class="flex flex-col pb-1">
										<div class="flex flex-row p-1 items-center">
											<Icon
												class="size-8"
												name={`url(blp:unlock_tradition)`}
												isUrl={true}
											/>
											<Divider vertical={true} />
											<div class="flex flex-col ml-1 flex-auto text-left">
												<L10n.Stylize
													class="text-secondary uppercase tracking-100 font-title-sm"
													text={item.def.Name ?? ""}
												/>
												<L10n.Stylize
													class="font-body-sm flex flex-auto w-full text-accent-3"
													text={item.unlock}
												/>
												<L10n.Stylize
													class="font-body-sm flex flex-auto w-full"
													text={item.def.Description ?? ""}
												/>
											</div>
										</div>
										<Show
											when={item != props.traditionsUnlocked[props.traditionsUnlocked.length - 1]}
										>
											<Divider />
										</Show>
									</div>
								)}
							</For>
						</TicketBox>
					</div>
				</div>
			</TicketBox>
		</Activatable>
	);
};

interface GovtSubHeaderProps {
	text: string;
	secondaryText?: boolean;
	class?: string;
}

const GovtCardSubHeader: Component<GovtSubHeaderProps> = (props) => {
	return (
		<L10n.Stylize
			text={props.text}
			class={`uppercase relative ${props.secondaryText ? "text-secondary-1" : "text-accent-4"} font-title-sm tracking-100 ${props.class}`}
		/>
	);
};

interface DividerProps {
	vertical?: true;
}

const Divider: Component<DividerProps> = (props) => {
	return <div class={`${props.vertical ? "h-full w-px mx-2" : "w-full h-px my-2"} flex bg-primary-3`} />;
};

defineLegacyComponent(
	"screen-government-chooser",
	{
		classNames: ["fullscreen, screen-government-chooser, flex, justify-center, items-center"],
	},
	(_attrs, _element) => {
		Input.setActiveContext(InputContext.Shell);
		return <GovernmentChooserComponent />;
	},
);

export const GovernmentChooser = ComponentRegistry.register({
	name: "GovernmentChooser",
	styles: [styles],
	createInstance: GovernmentChooserComponent,
});
